package com.lexorion.workforce.config;
import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.security.*;import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig {@Bean OpenAPI workforceOpenApi(){return new OpenAPI().info(new Info().title("Lexorion Workforce API").version("9F").description("Platform is the sole authority for the authenticated user, internal organization and workspace identities, tenant role, active membership, and product access. Workforce rejects incomplete authority context and never trusts X-User-ID, X-Organization-ID, X-Workspace-ID, X-Role, or body-supplied UUID/role values. employeeCode is the public workspace-scoped employee identifier; internal UUIDs remain private. ADMIN and ADMIN retain administration and direct-report team behavior. /me resolves only the trusted user's workspace-scoped employee mapping. /me/team derives exact direct reports from trusted workspaceId plus trusted platform user identity and Employee.reportingManager; MANAGER receives no indirect, department, designation, or administration scope, and EMPLOYEE is self-only. Employee listing uses page 0 and size 20 by default, maximum size 100, deterministic sorting, and workspace-scoped filters." )).components(new Components().addSecuritySchemes("bearer",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList("bearer"));}}
